package com.healthcare.portal.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service;
@Service public class EmailService { private final JavaMailSender sender; @Value("${app.mail.from:}") private String from; @Value("${app.frontend.url:http://localhost:5173}") private String frontend; public EmailService(JavaMailSender s){sender=s;} public void send(String to,String subject,String body){ if(to==null||to.isBlank()) return; SimpleMailMessage m=new SimpleMailMessage(); if(from!=null&&!from.isBlank())m.setFrom(from); m.setTo(to);m.setSubject(subject);m.setText(body);sender.send(m);} public void reset(String to,String token){send(to,"Healthcare Portal - Password Reset","Reset your password using this link (valid for a limited time):\n"+frontend+"/reset-password?token="+token);} public void otp(String to,String otp){send(to,"Healthcare Portal - Email Verification OTP","Your verification OTP is: "+otp+"\nIt expires soon.");} }